// Primaertemplate BEWUSST UNDEFINIERT: eine neue Enum-Auspraegung ohne Impl
// ist ein Compile-Fehler, keine Laufzeit-Luecke.
template <ReportForm F> struct ReportFormImpl;

template <class Impl>
concept ReportFormLike = requires(EmitContext const& ctx, BlockSpec const& b) {
    { Impl::kForm } -> std::convertible_to<ReportForm>;
    { Impl::kRequiredColumns } -> std::convertible_to<std::uint32_t>;
    { Impl::emit(ctx, b) } -> std::same_as<ReportStatus>;
};

template <ReportForm F> struct ReportFormBase {            // CRTP
    static constexpr ReportForm kForm = F;
    static constexpr std::string_view id() { return report_form_info(F).id; }
};

// Auffaecherung: index_sequence-Fold, jede Auspraegung ist ein eigener,
// vollstaendig instanziierter Codepfad (statischer Dispatch).
template <class Visitor>
constexpr auto visit_report_form(ReportForm f, Visitor&& v) -> ReportStatus {
    ReportStatus st = ReportStatus::UnknownForm;
    [&]<std::size_t... I>(std::index_sequence<I...>) {
        ((static_cast<std::size_t>(f) == I
              ? (st = v(std::integral_constant<ReportForm, static_cast<ReportForm>(I)>{}), 0)
              : 0), ...);
    }(std::make_index_sequence<kReportFormCount>{});
    return st;
}

// Vollstaendigkeits-Wache: JEDE Registry-Auspraegung hat eine Impl,
// und JEDE Impl erfuellt das Concept. Luecke = compile-time.
consteval bool all_report_forms_implemented() {
    bool ok = true;
    [&]<std::size_t... I>(std::index_sequence<I...>) {
        ((ok = ok && ReportFormLike<ReportFormImpl<static_cast<ReportForm>(I)>>), ...);
    }(std::make_index_sequence<kReportFormCount>{});
    return ok;
}
static_assert(all_report_forms_implemented(),
              "kReportFormRegistry: jede Form braucht ReportFormImpl<F> mit emit().");
